    // Footer Documentation Translations
    privacyTitle: "Política de Privacidad",
    privacyDescription: "Aprende cómo protegemos tus datos y privacidad",
    privacySection1: "1. Recopilación de Datos:",
    privacySection1Text: "Flappy Pi recopila solo los datos mínimos necesarios para proporcionar servicios del juego, como tu nombre de usuario, progreso del juego e ID de Pi Network.",
    privacySection2: "2. Datos de Pago:",
    privacySection2Text: "Cuando realizas pagos con Pi, procesamos los detalles de la transacción a través de Pi Network. En mainnet, las transacciones reales de Pi se procesan de forma segura por Pi Network.",
    privacySection3: "3. Cookies y Almacenamiento Local:",
    privacySection3Text: "Utilizamos almacenamiento local para guardar tu progreso del juego y preferencias. No se utilizan cookies de seguimiento de terceros.",
    privacySection4: "4. Compartir Datos:",
    privacySection4Text: "No vendemos ni compartimos tus datos personales con terceros, excepto cuando lo requiera la ley o para procesar pagos de Pi Network.",
    privacySection5: "5. Seguridad:",
    privacySection5Text: "Utilizamos medidas de seguridad estándar de la industria para proteger tus datos. Sin embargo, ningún sistema es 100% seguro.",
    privacySection6: "6. Privacidad de Menores:",
    privacySection6Text: "Flappy Pi no está destinado a menores de 13 años. No recopilamos conscientemente datos de menores de 13 años.",
    privacySection7: "7. Cambios en la Política:",
    privacySection7Text: "Podemos actualizar esta política. El uso continuado de la aplicación significa que aceptas la nueva política.",
    privacySection8: "8. Contacto:",
    privacySection8Text: "Para preguntas sobre privacidad, contacta a",
    privacyContactEmail: "support@www.flappypi.xyz",
    
    termsTitle: "Términos de Servicio",
    termsDescription: "Lee nuestros términos y condiciones",
    termsSection1: "1. Aceptación de Términos:",
    termsSection1Text: "Al usar Flappy Pi, aceptas estos Términos de Servicio. Si no estás de acuerdo, por favor no uses la aplicación.",
    termsSection2: "2. Pagos de Pi Network:",
    termsSection2Text: "Flappy Pi se integra con Pi Network para pagos dentro de la aplicación. Todos los pagos de Pi en modo de prueba usan Pi Testnet y no transfieren Pi real. Cuando se cambie a mainnet, ocurrirán transacciones reales de Pi. Siempre verifica el modo de pago antes de confirmar una transacción.",
    termsSection3: "3. Cuentas de Usuario:",
    termsSection3Text: "Eres responsable de mantener la confidencialidad de tu cuenta y de todas las actividades que ocurran bajo tu cuenta.",
    termsSection4: "4. Contenido del Juego:",
    termsSection4Text: "Todos los activos, gráficos y contenido del juego son propiedad de Flappy Pi y no pueden ser utilizados sin permiso.",
    termsSection5: "5. Limitación de Responsabilidad:",
    termsSection5Text: "Flappy Pi se proporciona \"tal como está\" sin garantías de ningún tipo. No somos responsables de ningún daño o pérdida resultante del uso de la aplicación o pagos de Pi Network.",
    termsSection6: "6. Cambios en los Términos:",
    termsSection6Text: "Podemos actualizar estos términos en cualquier momento. El uso continuado de la aplicación significa que aceptas los nuevos términos.",
    termsSection7: "7. Contacto:",
    termsSection7Text: "Para preguntas, contacta a",
    termsContactEmail: "support@www.flappypi.xyz",
    
    whitepaperTitle: "Whitepaper de Flappy Pi",
    whitepaperDescription: "Documentación técnica y hoja de ruta",
    whitepaperSection1: "1. Introducción",
    whitepaperSection1Text: "Flappy Pi es el primer juego Flappy Bird play-to-earn en Pi Network, combinando jugabilidad clásica con tecnología blockchain.",
    whitepaperSection2: "2. Mecánicas del Juego",
    whitepaperSection2Text: "Los jugadores controlan un pájaro, navegando a través de tuberías mientras recolectan monedas y evitan obstáculos. El juego presenta múltiples modos y potenciadores.",
    whitepaperSection3: "3. Integración con Pi Network",
    whitepaperSection3Text: "Flappy Pi utiliza la infraestructura de Pi Network para pagos seguros y autenticación de usuarios, asegurando una experiencia de juego fluida.",
    whitepaperSection4: "4. Tokenomics",
    whitepaperSection4Text: "Los jugadores pueden ganar criptomoneda Pi a través del juego, torneos y eventos especiales. La economía está diseñada para ser sostenible y justa.",
    whitepaperSection5: "5. Desarrollo Futuro",
    whitepaperSection5Text: "Las características planificadas incluyen coleccionables NFT, torneos avanzados y compatibilidad multiplataforma.",
    whitepaperSection6: "6. Contacto y Comunidad",
    whitepaperSection6Text: "Para preguntas, comentarios o consultas de asociación, contacta a",
    whitepaperContactEmail: "support@www.flappypi.xyz",
    whitepaperContactText: "¡Únete a nuestra comunidad para ayudar a dar forma al futuro de Flappy Pi!",
    
