    // Footer Documentation Translations
    privacyTitle: "Patakaran sa Privacy",
    privacyDescription: "Alamin kung paano namin pinoprotektahan ang iyong data at privacy",
    privacySection1: "1. Pagkolekta ng Data:",
    privacySection1Text: "Ang Flappy Pi ay kumokolekta lamang ng minimum na data na kinakailangan para magbigay ng game services, tulad ng iyong username, game progress, at Pi Network ID.",
    privacySection2: "2. Data ng Pagbabayad:",
    privacySection2Text: "Kapag gumawa ka ng Pi payments, pinoproseso namin ang mga detalye ng transaksyon sa pamamagitan ng Pi Network. Sa mainnet, ang mga tunay na Pi transactions ay pinoproseso nang ligtas ng Pi Network.",
    privacySection3: "3. Cookies & Local Storage:",
    privacySection3Text: "Ginagamit namin ang local storage para i-save ang iyong game progress at preferences. Walang third-party tracking cookies ang ginagamit.",
    privacySection4: "4. Pagbabahagi ng Data:",
    privacySection4Text: "Hindi namin ibinebenta o ibinabahagi ang iyong personal data sa mga third party, maliban sa kinakailangan ng batas o para iproseso ang Pi Network payments.",
    privacySection5: "5. Seguridad:",
    privacySection5Text: "Ginagamit namin ang industry-standard security measures para protektahan ang iyong data. Gayunpaman, walang sistema ang 100% secure.",
    privacySection6: "6. Privacy ng mga Bata:",
    privacySection6Text: "Ang Flappy Pi ay hindi intended para sa mga batang wala pang 13. Hindi namin sinasadyang kumolekta ng data mula sa mga batang wala pang 13.",
    privacySection7: "7. Mga Pagbabago sa Patakaran:",
    privacySection7Text: "Maaari naming i-update ang patakarang ito. Ang patuloy na paggamit ng app ay nangangahulugan na tinatanggap mo ang bagong patakaran.",
    privacySection8: "8. Kontak:",
    privacySection8Text: "Para sa mga tanong tungkol sa privacy, makipag-ugnayan sa",
    privacyContactEmail: "support@www.flappypi.xyz",
    
    termsTitle: "Mga Tuntunin ng Serbisyo",
    termsDescription: "Basahin ang aming mga tuntunin at kondisyon",
    termsSection1: "1. Pagtanggap ng mga Tuntunin:",
    termsSection1Text: "Sa paggamit ng Flappy Pi, sumasang-ayon ka sa mga Tuntunin ng Serbisyo na ito. Kung hindi ka sumasang-ayon, huwag gamitin ang app.",
    termsSection2: "2. Mga Pagbabayad sa Pi Network:",
    termsSection2Text: "Ang Flappy Pi ay nagsasama sa Pi Network para sa in-app payments. Lahat ng Pi payments sa test mode ay gumagamit ng Pi Testnet at hindi naglilipat ng tunay na Pi. Kapag na-switch sa mainnet, magaganap ang mga tunay na Pi transactions. Palaging i-check ang payment mode bago kumpirmahin ang isang transaksyon.",
    termsSection3: "3. Mga User Account:",
    termsSection3Text: "Responsable ka sa pagpapanatili ng confidentiality ng iyong account at para sa lahat ng aktibidad na nangyayari sa ilalim ng iyong account.",
    termsSection4: "4. Game Content:",
    termsSection4Text: "Lahat ng game assets, graphics, at content ay pag-aari ng Flappy Pi at hindi maaaring gamitin nang walang pahintulot.",
    termsSection5: "5. Limitasyon ng Liability:",
    termsSection5Text: "Ang Flappy Pi ay ibinibigay \"as is\" nang walang warranties ng anumang uri. Hindi kami liable para sa anumang damages o losses na resulta ng iyong paggamit ng app o Pi Network payments.",
    termsSection6: "6. Mga Pagbabago sa mga Tuntunin:",
    termsSection6Text: "Maaari naming i-update ang mga tuntuning ito anumang oras. Ang patuloy na paggamit ng app ay nangangahulugan na tinatanggap mo ang mga bagong tuntunin.",
    termsSection7: "7. Kontak:",
    termsSection7Text: "Para sa mga tanong, makipag-ugnayan sa",
    termsContactEmail: "support@www.flappypi.xyz",
    
