    whitepaperSection4: "4. Tokenomics",
    whitepaperSection4Text: "Ang mga player ay maaaring kumita ng Pi cryptocurrency sa pamamagitan ng gameplay, tournaments, at special events. Ang ekonomiya ay dinisenyo para maging sustainable at fair.",
