    // NPC Reserve Dialogs (50 dialogs)
    npcReserveDialog1: "Flappy Pi Treasury में आपका स्वागत है—जहां Pi प्रगति को बढ़ावा देता है!",
    npcReserveDialog2: "आपके flaps ने इस vault को भरने में मदद की!",
    npcReserveDialog3: "यह सिर्फ एक wallet नहीं है… यह हमारा भविष्य है।",
    npcReserveDialog4: "यहां का हर coin आपके पसंदीदा game का समर्थन करता है!",
    npcReserveDialog5: "Treasury funds = नई features, तेजी से!",
    npcReserveDialog6: "आसमान smart reserves पर बने हैं।",
    npcReserveDialog7: "नए game modes चाहते हैं? Treasury इसे संभव बनाता है।",
    npcReserveDialog8: "आपकी वजह से, हम हर दिन मजबूत उड़ रहे हैं!",
    npcReserveDialog9: "आपके खर्च किए गए हर Pi का एक हिस्सा Flappy Pi को बढ़ने में मदद करता है।",
    npcReserveDialog10: "Treasury हमारे ecosystem का दिल है।",
    npcReserveDialog11: "Server costs? Bug fixes? इस vault से covered!",
    npcReserveDialog12: "यहीं आपका support upgrades में बदल जाता है।",
    npcReserveDialog13: "Flaps से funding तक, सब कुछ जुड़ा है!",
    npcReserveDialog14: "आप सिर्फ player नहीं हैं—आप builder हैं।",
    npcReserveDialog15: "जब आप जीतते हैं, हम सभी जीतते हैं। Treasury शामिल!",
    npcReserveDialog16: "यह wallet developers, designers और sky magic को fuel देता है।",
    npcReserveDialog17: "इसे Pi engine room समझें!",
    npcReserveDialog18: "अधिक tournaments चाहते हैं? Treasury आपकी मदद करेगा!",
    npcReserveDialog19: "हम इसे आपको reward देने के लिए use करते हैं, community।",
    npcReserveDialog20: "यहां के coins = मजबूत, smooth skies!",
    npcReserveDialog21: "गर्व से उड़ें—आप भविष्य को fund कर रहे हैं।",
    npcReserveDialog22: "Marketing, events, new levels… यह सब कुछ संभव बनाता है।",
    npcReserveDialog23: "Transparency key है। Treasury reports जल्द आ रहे हैं!",
    npcReserveDialog24: "हम open skies में विश्वास करते हैं—और open wallets में!",
    npcReserveDialog25: "बड़े upgrades smart reserves से शुरू होते हैं।",
    npcReserveDialog26: "हमारा Treasury wallet public है—कभी भी check करें!",
    npcReserveDialog27: "आपका support = अधिक prizes और Pi rewards!",
    npcReserveDialog28: "यह vault leaderboards, events और fun को power देता है!",
    npcReserveDialog29: "हम हर Pi को game में वापस invest करते हैं।",
    npcReserveDialog30: "भविष्य की features पर vote करना चाहते हैं? वह आ रहा है!",
    npcReserveDialog31: "आप player-powered economy में उड़ रहे हैं।",
    npcReserveDialog32: "यहां का हर Pi support की कहानी बताता है।",
    npcReserveDialog33: "आपके ads, purchases और love—यहीं stored।",
    npcReserveDialog34: "Flappy Pi को sustainable रखने के लिए धन्यवाद!",
    npcReserveDialog35: "यह सिर्फ coins नहीं है—यह community effort है।",
    npcReserveDialog36: "पंखों से funds तक!",
    npcReserveDialog37: "हम कुछ बहुत ऊंचा बना रहे हैं—साथ में।",
    npcReserveDialog38: "अधिक players = अधिक Pi = अधिक power!",
    npcReserveDialog39: "Flappy का भविष्य यहीं रहता है।",
    npcReserveDialog40: "यह आपका Treasury भी है—धन्यवाद!",
    npcReserveDialog41: "Taps से trust तक, cycle जारी है।",
    npcReserveDialog42: "Treasury = भविष्य के Pi champions के लिए power!",
    npcReserveDialog43: "मजबूत flap करें, smart support करें!",
    npcReserveDialog44: "हमारा Pi motion में रहता है—आपकी मदद से।",
    npcReserveDialog45: "हम यहां deposited हर Pi के साथ मजबूत हैं।",
    npcReserveDialog46: "यही तरीका है जिससे fun funded होती है!",
    npcReserveDialog47: "चलिए एक ऐसा game बनाते हैं जो flappers की पीढ़ियों तक चले!",
    npcReserveDialog48: "यह vault developers, players और pioneers के लिए है।",
    npcReserveDialog49: "आपका gameplay flock को fuel देता है।",
    npcReserveDialog50: "हमारे skies support पर चलते हैं—और आपने बहुत कुछ दिया है!",
    
