    // Footer Documentation Translations
    privacyTitle: "गोपनीयता नीति",
    privacyDescription: "जानें कि हम आपके डेटा और गोपनीयता की रक्षा कैसे करते हैं",
    privacySection1: "1. डेटा संग्रह:",
    privacySection1Text: "Flappy Pi केवल न्यूनतम डेटा एकत्र करता है जो गेम सेवाएं प्रदान करने के लिए आवश्यक है, जैसे आपका उपयोगकर्ता नाम, गेम प्रगति, और Pi Network ID।",
    privacySection2: "2. भुगतान डेटा:",
    privacySection2Text: "जब आप Pi भुगतान करते हैं, तो हम Pi Network के माध्यम से लेन-देन विवरण संसाधित करते हैं। मेननेट में, वास्तविक Pi लेन-देन Pi Network द्वारा सुरक्षित रूप से संसाधित किए जाते हैं।",
    privacySection3: "3. कुकीज़ और लोकल स्टोरेज:",
    privacySection3Text: "हम आपकी गेम प्रगति और प्राथमिकताओं को सहेजने के लिए लोकल स्टोरेज का उपयोग करते हैं। कोई तृतीय-पक्ष ट्रैकिंग कुकीज़ नहीं हैं।",
    privacySection4: "4. डेटा साझाकरण:",
    privacySection4Text: "हम आपके व्यक्तिगत डेटा को तृतीय पक्षों के साथ नहीं बेचते या साझा करते, सिवाय कानून द्वारा आवश्यक या Pi Network भुगतान संसाधित करने के लिए।",
    privacySection5: "5. सुरक्षा:",
    privacySection5Text: "हम आपके डेटा की रक्षा के लिए उद्योग-मानक सुरक्षा उपायों का उपयोग करते हैं। हालांकि, कोई भी सिस्टम 100% सुरक्षित नहीं है।",
    privacySection6: "6. बच्चों की गोपनीयता:",
    privacySection6Text: "Flappy Pi 13 वर्ष से कम उम्र के बच्चों के लिए नहीं है। हम जानबूझकर 13 वर्ष से कम उम्र के बच्चों से डेटा नहीं एकत्र करते।",
    privacySection7: "7. नीति में परिवर्तन:",
    privacySection7Text: "हम इस नीति को अपडेट कर सकते हैं। ऐप का निरंतर उपयोग का मतलब है कि आप नई नीति को स्वीकार करते हैं।",
    privacySection8: "8. संपर्क:",
    privacySection8Text: "गोपनीयता प्रश्नों के लिए, संपर्क करें",
    privacyContactEmail: "support@www.flappypi.xyz",
    
    termsTitle: "सेवा की शर्तें",
    termsDescription: "हमारी शर्तें और शर्तें पढ़ें",
    termsSection1: "1. शर्तों की स्वीकृति:",
    termsSection1Text: "Flappy Pi का उपयोग करके, आप इन सेवा की शर्तों से सहमत होते हैं। यदि आप सहमत नहीं हैं, तो कृपया ऐप का उपयोग न करें।",
    termsSection2: "2. Pi Network भुगतान:",
    termsSection2Text: "Flappy Pi इन-ऐप भुगतान के लिए Pi Network के साथ एकीकृत होता है। टेस्ट मोड में सभी Pi भुगतान Pi Testnet का उपयोग करते हैं और वास्तविक Pi स्थानांतरित नहीं करते। जब मेननेट पर स्विच किया जाता है, तो वास्तविक Pi लेन-देन होंगे। लेन-देन की पुष्टि करने से पहले हमेशा भुगतान मोड जांचें।",
    termsSection3: "3. उपयोगकर्ता खाते:",
    termsSection3Text: "आप अपने खाते की गोपनीयता बनाए रखने और अपने खाते के तहत होने वाली सभी गतिविधियों के लिए जिम्मेदार हैं।",
    termsSection4: "4. गेम सामग्री:",
    termsSection4Text: "सभी गेम संपत्तियां, ग्राफिक्स और सामग्री Flappy Pi की संपत्ति हैं और बिना अनुमति के उपयोग नहीं की जा सकती।",
    termsSection5: "5. देयता की सीमा:",
    termsSection5Text: "Flappy Pi किसी भी प्रकार की वारंटी के बिना \"जैसा है\" प्रदान किया जाता है। हम आपके ऐप या Pi Network भुगतान के उपयोग के परिणामस्वरूप किसी भी क्षति या हानि के लिए उत्तरदायी नहीं हैं।",
    termsSection6: "6. शर्तों में परिवर्तन:",
    termsSection6Text: "हम किसी भी समय इन शर्तों को अपडेट कर सकते हैं। ऐप का निरंतर उपयोग का मतलब है कि आप नई शर्तों को स्वीकार करते हैं।",
    termsSection7: "7. संपर्क:",
    termsSection7Text: "प्रश्नों के लिए, संपर्क करें",
    termsContactEmail: "support@www.flappypi.xyz",
    
