    // Footer Documentation Translations
    privacyTitle: "Kebijakan Privasi",
    privacyDescription: "Pelajari bagaimana kami melindungi data dan privasi Anda",
    privacySection1: "1. Pengumpulan Data:",
    privacySection1Text: "Flappy Pi hanya mengumpulkan data minimal yang diperlukan untuk menyediakan layanan game, seperti nama pengguna, kemajuan game, dan ID Pi Network Anda.",
    privacySection2: "2. Data Pembayaran:",
    privacySection2Text: "Ketika Anda melakukan pembayaran Pi, kami memproses detail transaksi melalui Pi Network. Di mainnet, transaksi Pi yang sebenarnya diproses dengan aman oleh Pi Network.",
    privacySection3: "3. Cookie & Penyimpanan Lokal:",
    privacySection3Text: "Kami menggunakan penyimpanan lokal untuk menyimpan kemajuan game dan preferensi Anda. Tidak ada cookie pelacakan pihak ketiga yang digunakan.",
    privacySection4: "4. Berbagi Data:",
    privacySection4Text: "Kami tidak menjual atau membagikan data pribadi Anda kepada pihak ketiga, kecuali seperti yang disyaratkan oleh hukum atau untuk memproses pembayaran Pi Network.",
    privacySection5: "5. Keamanan:",
    privacySection5Text: "Kami menggunakan langkah-langkah keamanan standar industri untuk melindungi data Anda. Namun, tidak ada sistem yang 100% aman.",
    privacySection6: "6. Privasi Anak:",
    privacySection6Text: "Flappy Pi tidak ditujukan untuk anak-anak di bawah 13 tahun. Kami tidak secara sengaja mengumpulkan data dari anak-anak di bawah 13 tahun.",
    privacySection7: "7. Perubahan Kebijakan:",
    privacySection7Text: "Kami dapat memperbarui kebijakan ini. Penggunaan aplikasi yang berkelanjutan berarti Anda menerima kebijakan baru.",
    privacySection8: "8. Kontak:",
    privacySection8Text: "Untuk pertanyaan privasi, hubungi",
    privacyContactEmail: "support@www.flappypi.xyz",
    
    termsTitle: "Ketentuan Layanan",
    termsDescription: "Baca ketentuan dan kondisi kami",
    termsSection1: "1. Penerimaan Ketentuan:",
    termsSection1Text: "Dengan menggunakan Flappy Pi, Anda setuju dengan Ketentuan Layanan ini. Jika Anda tidak setuju, harap jangan gunakan aplikasi.",
    termsSection2: "2. Pembayaran Pi Network:",
    termsSection2Text: "Flappy Pi terintegrasi dengan Pi Network untuk pembayaran dalam aplikasi. Semua pembayaran Pi dalam mode test menggunakan Pi Testnet dan tidak mentransfer Pi yang sebenarnya. Ketika dialihkan ke mainnet, transaksi Pi yang sebenarnya akan terjadi. Selalu periksa mode pembayaran sebelum mengkonfirmasi transaksi.",
    termsSection3: "3. Akun Pengguna:",
    termsSection3Text: "Anda bertanggung jawab untuk menjaga kerahasiaan akun Anda dan untuk semua aktivitas yang terjadi di bawah akun Anda.",
    termsSection4: "4. Konten Game:",
    termsSection4Text: "Semua aset game, grafik, dan konten adalah milik Flappy Pi dan tidak dapat digunakan tanpa izin.",
    termsSection5: "5. Pembatasan Tanggung Jawab:",
    termsSection5Text: "Flappy Pi disediakan \"sebagaimana adanya\" tanpa jaminan apa pun. Kami tidak bertanggung jawab atas kerusakan atau kerugian yang diakibatkan oleh penggunaan aplikasi atau pembayaran Pi Network Anda.",
    termsSection6: "6. Perubahan Ketentuan:",
    termsSection6Text: "Kami dapat memperbarui ketentuan ini kapan saja. Penggunaan aplikasi yang berkelanjutan berarti Anda menerima ketentuan baru.",
    termsSection7: "7. Kontak:",
    termsSection7Text: "Untuk pertanyaan, hubungi",
    termsContactEmail: "support@www.flappypi.xyz",
    
    whitepaperTitle: "Flappy Pi Whitepaper",
    whitepaperDescription: "Dokumentasi teknis dan roadmap",
    whitepaperSection1: "1. Pendahuluan",
    whitepaperSection1Text: "Flappy Pi adalah game play-to-earn Flappy Bird pertama di Pi Network, menggabungkan gameplay klasik dengan teknologi blockchain.",
    whitepaperSection2: "2. Mekanisme Game",
    whitepaperSection2Text: "Pemain mengontrol seekor burung, menavigasi melalui pipa sambil mengumpulkan koin dan menghindari rintangan. Game memiliki berbagai mode dan power-up.",
    whitepaperSection3: "3. Integrasi Pi Network",
    whitepaperSection3Text: "Flappy Pi menggunakan infrastruktur Pi Network untuk pembayaran yang aman dan autentikasi pengguna, memastikan pengalaman gaming yang mulus.",
    whitepaperSection4: "4. Tokenomics",
    whitepaperSection4Text: "Pemain dapat memperoleh kriptocurrency Pi melalui gameplay, turnamen, dan acara khusus. Ekonomi dirancang untuk berkelanjutan dan adil.",
    whitepaperSection5: "5. Pengembangan Masa Depan",
    whitepaperSection5Text: "Fitur yang direncanakan termasuk NFT collectibles, turnamen lanjutan, dan kompatibilitas cross-platform.",
    whitepaperSection6: "6. Kontak & Komunitas",
    whitepaperSection6Text: "Untuk pertanyaan, umpan balik, atau pertanyaan kemitraan, hubungi",
    whitepaperContactEmail: "support@www.flappypi.xyz",
    whitepaperContactText: "Bergabunglah dengan komunitas kami untuk membantu membentuk masa depan Flappy Pi!",
    
