    // Footer Documentation Translations
    privacyTitle: "Política de Privacidade",
    privacyDescription: "Saiba como protegemos seus dados e privacidade",
    privacySection1: "1. Coleta de Dados:",
    privacySection1Text: "O Flappy Pi coleta apenas os dados mínimos necessários para fornecer serviços de jogo, como seu nome de usuário, progresso do jogo e ID do Pi Network.",
    privacySection2: "2. Dados de Pagamento:",
    privacySection2Text: "Quando você faz pagamentos Pi, processamos os detalhes da transação através do Pi Network. Na mainnet, transações Pi reais são processadas com segurança pelo Pi Network.",
    privacySection3: "3. Cookies e Armazenamento Local:",
    privacySection3Text: "Usamos armazenamento local para salvar seu progresso no jogo e preferências. Nenhum cookie de rastreamento de terceiros é usado.",
    privacySection4: "4. Compartilhamento de Dados:",
    privacySection4Text: "Não vendemos ou compartilhamos seus dados pessoais com terceiros, exceto conforme exigido por lei ou para processar pagamentos do Pi Network.",
    privacySection5: "5. Segurança:",
    privacySection5Text: "Usamos medidas de segurança padrão da indústria para proteger seus dados. No entanto, nenhum sistema é 100% seguro.",
    privacySection6: "6. Privacidade das Crianças:",
    privacySection6Text: "O Flappy Pi não é destinado a crianças menores de 13 anos. Não coletamos intencionalmente dados de crianças menores de 13 anos.",
    privacySection7: "7. Mudanças na Política:",
    privacySection7Text: "Podemos atualizar esta política. O uso contínuo do aplicativo significa que você aceita a nova política.",
    privacySection8: "8. Contato:",
    privacySection8Text: "Para questões de privacidade, entre em contato com",
    privacyContactEmail: "support@www.flappypi.xyz",
    
    termsTitle: "Termos de Serviço",
    termsDescription: "Leia nossos termos e condições",
    termsSection1: "1. Aceitação dos Termos:",
    termsSection1Text: "Ao usar o Flappy Pi, você concorda com estes Termos de Serviço. Se você não concordar, por favor não use o aplicativo.",
    termsSection2: "2. Pagamentos Pi Network:",
    termsSection2Text: "O Flappy Pi integra-se ao Pi Network para pagamentos no aplicativo. Todos os pagamentos Pi no modo de teste usam o Pi Testnet e não transferem Pi real. Quando mudado para mainnet, transações Pi reais ocorrerão. Sempre verifique o modo de pagamento antes de confirmar uma transação.",
    termsSection3: "3. Contas de Usuário:",
    termsSection3Text: "Você é responsável por manter a confidencialidade de sua conta e por todas as atividades que ocorrem sob sua conta.",
    termsSection4: "4. Conteúdo do Jogo:",
    termsSection4Text: "Todos os ativos, gráficos e conteúdo do jogo são propriedade do Flappy Pi e não podem ser usados sem permissão.",
    termsSection5: "5. Limitação de Responsabilidade:",
    termsSection5Text: "O Flappy Pi é fornecido \"como está\" sem garantias de qualquer tipo. Não somos responsáveis por quaisquer danos ou perdas resultantes do uso do aplicativo ou pagamentos do Pi Network.",
    termsSection6: "6. Mudanças nos Termos:",
    termsSection6Text: "Podemos atualizar estes termos a qualquer momento. O uso contínuo do aplicativo significa que você aceita os novos termos.",
    termsSection7: "7. Contato:",
    termsSection7Text: "Para perguntas, entre em contato com",
    termsContactEmail: "support@www.flappypi.xyz",
    
    whitepaperTitle: "Flappy Pi Whitepaper",
    whitepaperDescription: "Documentação técnica e roadmap",
    whitepaperSection1: "1. Introdução",
    whitepaperSection1Text: "O Flappy Pi é o primeiro jogo play-to-earn Flappy Bird no Pi Network, combinando gameplay clássico com tecnologia blockchain.",
    whitepaperSection2: "2. Mecânicas do Jogo",
    whitepaperSection2Text: "Os jogadores controlam um pássaro, navegando através de tubos enquanto coletam moedas e evitam obstáculos. O jogo apresenta múltiplos modos e power-ups.",
    whitepaperSection3: "3. Integração Pi Network",
    whitepaperSection3Text: "O Flappy Pi usa a infraestrutura do Pi Network para pagamentos seguros e autenticação de usuários, garantindo uma experiência de jogo perfeita.",
    whitepaperSection4: "4. Tokenomics",
    whitepaperSection4Text: "Os jogadores podem ganhar criptomoeda Pi através de gameplay, torneios e eventos especiais. A economia é projetada para ser sustentável e justa.",
    whitepaperSection5: "5. Desenvolvimento Futuro",
    whitepaperSection5Text: "Recursos planejados incluem NFT collectibles, torneios avançados e compatibilidade cross-platform.",
    whitepaperSection6: "6. Contato e Comunidade",
    whitepaperSection6Text: "Para perguntas, feedback ou consultas de parceria, entre em contato com",
    whitepaperContactEmail: "support@www.flappypi.xyz",
