    privacyDescription: "Узнайте, как мы защищаем ваши данные и конфиденциальность",
    privacySection1: "1. Сбор данных:",
    privacySection1Text: "Flappy Pi собирает только минимальные данные, необходимые для предоставления игровых услуг, такие как ваше имя пользователя, прогресс игры и ID Pi Network.",
    privacySection2: "2. Данные платежей:",
