    privacySection3: "3. Файлы cookie и локальное хранилище:",
    privacySection3Text: "Мы используем локальное хранилище для сохранения вашего игрового прогресса и настроек. Файлы cookie сторонних трекеров не используются.",
    privacySection4: "4. Обмен данными:",
    privacySection4Text: "Мы не продаем и не передаем ваши личные данные третьим лицам, кроме случаев, предусмотренных законом или для обработки платежей Pi Network.",
    privacySection5: "5. Безопасность:",
    privacySection5Text: "Мы используем стандартные меры безопасности отрасли для защиты ваших данных. Однако ни одна система не является 100% безопасной.",
