    reserveBackButton: "Geri",
    npcReserveDialog: "Flappy Pi Reserve bizim topluluk hazinemizdir! Tüm oyuncular için yeni özellikler, turnuvalar ve ödüller finanse etmeye yardımcı olur. Her satın alma ve reklam oyunun büyümesine yardımcı olur. Sürüyü desteklediğiniz için teşekkürler!",
    
    // NPC Reserve Dialogs (50 dialogs)
    npcReserveDialog1: "Flappy Pi Hazine'sine hoş geldiniz—Pi'nin ilerlemeyi beslediği yer!",
    npcReserveDialog2: "Kanat çırpışlarınız bu kasayı doldurmaya yardımcı oldu!",
    npcReserveDialog3: "Bu sadece bir cüzdan değil… bu bizim geleceğimiz.",
    npcReserveDialog4: "Buradaki her jeton sevdiğiniz oyunu destekler!",
    npcReserveDialog5: "Hazine fonları = yeni özellikler, daha hızlı!",
    npcReserveDialog6: "Gökler akıllı rezervler üzerine inşa edilmiştir.",
    npcReserveDialog7: "Yeni oyun modları ister misiniz? Hazine bunu mümkün kılar.",
    npcReserveDialog8: "Sayenizde her gün daha güçlü uçuyoruz!",
    npcReserveDialog9: "Harcadığınız her Pi'nin bir kısmı Flappy Pi'nin büyümesine yardımcı olur.",
    npcReserveDialog10: "Hazine ekosistemimizin kalbidir.",
    npcReserveDialog11: "Sunucu maliyetleri? Hata düzeltmeleri? Bu kasa tarafından karşılanır!",
    npcReserveDialog12: "Burası desteğinizin geliştirmelere dönüştüğü yerdir.",
    npcReserveDialog13: "Kanat çırpışlarından finansmana, her şey bağlantılı!",
    npcReserveDialog14: "Sadece bir oyuncu değilsiniz—bir inşaatçısınız.",
    npcReserveDialog15: "Kazandığınızda, hepimiz kazanırız. Hazine dahil!",
    npcReserveDialog16: "Bu cüzdan geliştiricileri, tasarımcıları ve gökyüzü sihrini besler.",
    npcReserveDialog17: "Bunu Pi makine odası olarak düşünün!",
    npcReserveDialog18: "Daha fazla turnuva ister misiniz? Hazine sizi korur!",
    npcReserveDialog19: "Bunu SİZİ, topluluğu ödüllendirmek için kullanıyoruz.",
    npcReserveDialog20: "Buradaki jetonlar = daha güçlü, daha pürüzsüz gökyüzü!",
    npcReserveDialog21: "Gururla uçun—geleceği finanse ediyorsunuz.",
    npcReserveDialog22: "Pazarlama, etkinlikler, yeni seviyeler… bunlar her şeyi mümkün kılar.",
    npcReserveDialog23: "Şeffaflık anahtardır. Hazine raporları yakında!",
    npcReserveDialog24: "Açık gökyüzüne—ve açık cüzdanlara inanıyoruz!",
    npcReserveDialog25: "Büyük geliştirmeler akıllı rezervlerle başlar.",
    npcReserveDialog26: "Hazine cüzdanımız herkese açık—istediğiniz zaman kontrol edin!",
    npcReserveDialog27: "Desteğiniz = daha fazla ödül ve Pi ödülü!",
    npcReserveDialog28: "Bu kasa liderlik tablolarını, etkinlikleri ve eğlenceyi besler!",
    npcReserveDialog29: "Her Pi'yi oyuna geri yatırıyoruz.",
    npcReserveDialog30: "Gelecekteki özellikler için oy vermek ister misiniz? Bu geliyor!",
    npcReserveDialog31: "Oyuncu güdümlü bir ekonomide uçuyorsunuz.",
    npcReserveDialog32: "Buradaki her Pi bir destek hikayesi anlatır.",
    npcReserveDialog33: "Reklamlarınız, satın alımlarınız ve sevginiz—burada saklanır.",
    npcReserveDialog34: "Flappy Pi'yi sürdürülebilir tuttuğunuz için teşekkürler!",
    npcReserveDialog35: "Bu sadece jeton değil—bu topluluk çabası.",
    npcReserveDialog36: "Tüylerden fonlara!",
    npcReserveDialog37: "Çok yüksek bir şey inşa ediyoruz—birlikte.",
    npcReserveDialog38: "Daha fazla oyuncu = daha fazla Pi = daha fazla güç!",
    npcReserveDialog39: "Flappy'nin geleceği burada yaşar.",
    npcReserveDialog40: "Bu da sizin Hazine'niz—teşekkürler!",
    npcReserveDialog41: "Dokunuşlardan güvene, döngü devam eder.",
    npcReserveDialog42: "Hazine = gelecekteki Pi şampiyonları için güç!",
    npcReserveDialog43: "Güçlü kanat çırpın, akıllıca destekleyin!",
    npcReserveDialog44: "Pi'miz hareket halinde kalır—sizin yardımınızla.",
    npcReserveDialog45: "Buraya yatırılan her Pi ile daha güçlüyüz.",
    npcReserveDialog46: "Eğlence böyle finanse edilir!",
    npcReserveDialog47: "Flapper nesilleri için sürecek bir oyun inşa edelim!",
    npcReserveDialog48: "Bu kasa geliştiriciler, oyuncular ve öncüler içindir.",
    npcReserveDialog49: "Oyun oynayışınız sürüyü besler.",
    npcReserveDialog50: "Gökyüzümüz destekle çalışır—ve çok şey verdiniz!",
