    // Footer Documentation Translations
    privacyTitle: "Gizlilik Politikası",
    privacyDescription: "Verilerinizi ve gizliliğinizi nasıl koruduğumuzu öğrenin",
    privacySection1: "1. Veri Toplama:",
    privacySection1Text: "Flappy Pi, oyun hizmetleri sağlamak için gerekli minimum verileri toplar, kullanıcı adınız, oyun ilerlemeniz ve Pi Network ID'niz gibi.",
    privacySection2: "2. Ödeme Verileri:",
    privacySection2Text: "Pi ödemeleri yaptığınızda, işlem detaylarını Pi Network aracılığıyla işleriz. Ana ağda, gerçek Pi işlemleri Pi Network tarafından güvenli bir şekilde işlenir.",
    privacySection3: "3. Çerezler ve Yerel Depolama:",
    privacySection3Text: "Oyun ilerlemenizi ve tercihlerinizi kaydetmek için yerel depolama kullanırız. Üçüncü taraf izleme çerezleri kullanılmaz.",
    privacySection4: "4. Veri Paylaşımı:",
    privacySection4Text: "Kişisel verilerinizi üçüncü taraflarla satmaz veya paylaşmayız, yasa gereği gerekli olmadıkça veya Pi Network ödemelerini işlemek için.",
    privacySection5: "5. Güvenlik:",
    privacySection5Text: "Verilerinizi korumak için endüstri standardı güvenlik önlemleri kullanırız. Ancak, hiçbir sistem %100 güvenli değildir.",
    privacySection6: "6. Çocuk Gizliliği:",
    privacySection6Text: "Flappy Pi 13 yaşın altındaki çocuklar için tasarlanmamıştır. 13 yaşın altındaki çocuklardan kasıtlı olarak veri toplamayız.",
    privacySection7: "7. Politika Değişiklikleri:",
    privacySection7Text: "Bu politikayı güncelleyebiliriz. Uygulamayı kullanmaya devam etmek, yeni politikayı kabul ettiğiniz anlamına gelir.",
    privacySection8: "8. İletişim:",
    privacySection8Text: "Gizlilik soruları için iletişime geçin",
    privacyContactEmail: "support@www.flappypi.xyz",
    
    termsTitle: "Hizmet Şartları",
    termsDescription: "Şartlarımızı ve koşullarımızı okuyun",
    termsSection1: "1. Şartların Kabulü:",
    termsSection1Text: "Flappy Pi'yi kullanarak bu Hizmet Şartlarını kabul edersiniz. Kabul etmiyorsanız, lütfen uygulamayı kullanmayın.",
    termsSection2: "2. Pi Network Ödemeleri:",
    termsSection2Text: "Flappy Pi, uygulama içi ödemeler için Pi Network ile entegre olur. Test modundaki tüm Pi ödemeleri Pi Testnet kullanır ve gerçek Pi transfer etmez. Ana ağa geçildiğinde gerçek Pi işlemleri gerçekleşecektir. Bir işlemi onaylamadan önce her zaman ödeme modunu kontrol edin.",
    termsSection3: "3. Kullanıcı Hesapları:",
    termsSection3Text: "Hesabınızın gizliliğini korumaktan ve hesabınız altında gerçekleşen tüm faaliyetlerden sorumlusunuz.",
    termsSection4: "4. Oyun İçeriği:",
    termsSection4Text: "Tüm oyun varlıkları, grafikler ve içerik Flappy Pi'nin mülkiyetindedir ve izinsiz kullanılamaz.",
    termsSection5: "5. Sorumluluk Sınırlaması:",
    termsSection5Text: "Flappy Pi \"olduğu gibi\" herhangi bir garanti olmaksızın sağlanır. Uygulama veya Pi Network ödemelerinin kullanımından kaynaklanan herhangi bir hasar veya kayıp için sorumlu değiliz.",
