    // Footer Documentation Translations
    privacyTitle: "Chính sách Bảo mật",
    privacyDescription: "Tìm hiểu cách chúng tôi bảo vệ dữ liệu và quyền riêng tư của bạn",
    privacySection1: "1. Thu thập Dữ liệu:",
    privacySection1Text: "Flappy Pi chỉ thu thập dữ liệu tối thiểu cần thiết để cung cấp dịch vụ trò chơi, như tên người dùng, tiến độ trò chơi và ID Pi Network của bạn.",
    privacySection2: "2. Dữ liệu Thanh toán:",
    privacySection2Text: "Khi bạn thực hiện thanh toán Pi, chúng tôi xử lý chi tiết giao dịch thông qua Pi Network. Trên mainnet, các giao dịch Pi thực sẽ được xử lý an toàn bởi Pi Network.",
    privacySection3: "3. Cookie và Lưu trữ Cục bộ:",
    privacySection3Text: "Chúng tôi sử dụng lưu trữ cục bộ để lưu tiến độ trò chơi và tùy chọn của bạn. Không sử dụng cookie theo dõi của bên thứ ba.",
    privacySection4: "4. Chia sẻ Dữ liệu:",
    privacySection4Text: "Chúng tôi không bán hoặc chia sẻ dữ liệu cá nhân của bạn với bên thứ ba, trừ khi được yêu cầu bởi luật pháp hoặc để xử lý thanh toán Pi Network.",
    privacySection5: "5. Bảo mật:",
    privacySection5Text: "Chúng tôi sử dụng các biện pháp bảo mật tiêu chuẩn của ngành để bảo vệ dữ liệu của bạn. Tuy nhiên, không có hệ thống nào 100% an toàn.",
    privacySection6: "6. Quyền riêng tư của Trẻ em:",
    privacySection6Text: "Flappy Pi không dành cho trẻ em dưới 13 tuổi. Chúng tôi không thu thập có chủ ý dữ liệu từ trẻ em dưới 13 tuổi.",
    privacySection7: "7. Thay đổi Chính sách:",
    privacySection7Text: "Chúng tôi có thể cập nhật chính sách này. Việc tiếp tục sử dụng ứng dụng có nghĩa là bạn chấp nhận chính sách mới.",
    privacySection8: "8. Liên hệ:",
    privacySection8Text: "Đối với câu hỏi về quyền riêng tư, liên hệ",
    privacyContactEmail: "support@www.flappypi.xyz",
    
    termsTitle: "Điều khoản Dịch vụ",
    termsDescription: "Đọc điều khoản và điều kiện của chúng tôi",
    termsSection1: "1. Chấp nhận Điều khoản:",
    termsSection1Text: "Bằng cách sử dụng Flappy Pi, bạn đồng ý với các Điều khoản Dịch vụ này. Nếu bạn không đồng ý, vui lòng không sử dụng ứng dụng.",
    termsSection2: "2. Thanh toán Pi Network:",
    termsSection2Text: "Flappy Pi tích hợp với Pi Network cho thanh toán trong ứng dụng. Tất cả thanh toán Pi ở chế độ thử nghiệm sử dụng Pi Testnet và không chuyển Pi thực. Khi chuyển sang mainnet, các giao dịch Pi thực sẽ xảy ra. Luôn kiểm tra chế độ thanh toán trước khi xác nhận giao dịch.",
    termsSection3: "3. Tài khoản Người dùng:",
    termsSection3Text: "Bạn chịu trách nhiệm duy trì tính bảo mật của tài khoản và tất cả hoạt động xảy ra dưới tài khoản của bạn.",
    termsSection4: "4. Nội dung Trò chơi:",
    termsSection4Text: "Tất cả tài sản, đồ họa và nội dung trò chơi là tài sản của Flappy Pi và không thể sử dụng mà không có sự cho phép.",
    termsSection5: "5. Giới hạn Trách nhiệm:",
    termsSection5Text: "Flappy Pi được cung cấp \"nguyên trạng\" mà không có bất kỳ bảo đảm nào. Chúng tôi không chịu trách nhiệm về bất kỳ thiệt hại hoặc mất mát nào do việc sử dụng ứng dụng hoặc thanh toán Pi Network.",
    termsSection6: "6. Thay đổi Điều khoản:",
    termsSection6Text: "Chúng tôi có thể cập nhật các điều khoản này bất cứ lúc nào. Việc tiếp tục sử dụng ứng dụng có nghĩa là bạn chấp nhận các điều khoản mới.",
    termsSection7: "7. Liên hệ:",
    termsSection7Text: "Đối với câu hỏi, liên hệ",
    termsContactEmail: "support@www.flappypi.xyz",
    
    whitepaperTitle: "Flappy Pi Whitepaper",
    whitepaperDescription: "Tài liệu kỹ thuật và lộ trình",
    whitepaperSection1: "1. Giới thiệu",
    whitepaperSection1Text: "Flappy Pi là trò chơi play-to-earn Flappy Bird đầu tiên trên Pi Network, kết hợp gameplay cổ điển với công nghệ blockchain.",
    whitepaperSection2: "2. Cơ chế Trò chơi",
    whitepaperSection2Text: "Người chơi điều khiển một con chim, điều hướng qua các ống trong khi thu thập xu và tránh chướng ngại vật. Trò chơi có nhiều chế độ và power-up.",
    whitepaperSection3: "3. Tích hợp Pi Network",
    whitepaperSection3Text: "Flappy Pi sử dụng cơ sở hạ tầng Pi Network cho thanh toán an toàn và xác thực người dùng, đảm bảo trải nghiệm chơi game mượt mà.",
    whitepaperSection4: "4. Tokenomics",
    whitepaperSection4Text: "Người chơi có thể kiếm tiền điện tử Pi thông qua gameplay, giải đấu và sự kiện đặc biệt. Nền kinh tế được thiết kế để bền vững và công bằng.",
    whitepaperSection5: "5. Phát triển Tương lai",
    whitepaperSection5Text: "Các tính năng dự kiến bao gồm NFT collectibles, giải đấu nâng cao và khả năng tương thích đa nền tảng.",
    whitepaperSection6: "6. Liên hệ và Cộng đồng",
    whitepaperSection6Text: "Đối với câu hỏi, phản hồi hoặc yêu cầu hợp tác, liên hệ",
    whitepaperContactEmail: "support@www.flappypi.xyz",
    whitepaperContactText: "Tham gia cộng đồng của chúng tôi để giúp định hình tương lai của Flappy Pi!",
    
