    privacySection5Text: "เราใช้มาตรการความปลอดภัยมาตรฐานของอุตสาหกรรมเพื่อปกป้องข้อมูลของคุณ อย่างไรก็ตาม ไม่มีระบบใดที่ปลอดภัย 100%",
    privacySection6: "6. ความเป็นส่วนตัวของเด็ก:",
    privacySection6Text: "Flappy Pi ไม่ได้ออกแบบมาสำหรับเด็กอายุต่ำกว่า 13 ปี เราไม่เก็บรวบรวมข้อมูลจากเด็กอายุต่ำกว่า 13 ปีโดยเจตนา",
    privacySection7: "7. การเปลี่ยนแปลงนโยบาย:",
