    termsTitle: "ข้อกำหนดการให้บริการ",
    termsDescription: "อ่านข้อกำหนดและเงื่อนไขของเรา",
    termsSection1: "1. การยอมรับข้อกำหนด:",
    termsSection1Text: "การใช้ Flappy Pi หมายความว่าคุณยอมรับข้อกำหนดการให้บริการเหล่านี้ หากคุณไม่เห็นด้วย โปรดอย่าใช้แอป",
    termsSection2: "2. การชำระเงิน Pi Network:",
