    termsSection4: "4. เนื้อหาเกม:",
    termsSection4Text: "สินทรัพย์ กราฟิก และเนื้อหาเกมทั้งหมดเป็นกรรมสิทธิ์ของ Flappy Pi และไม่สามารถใช้ได้โดยไม่ได้รับอนุญาต",
    termsSection5: "5. การจำกัดความรับผิดชอบ:",
    termsSection5Text: "Flappy Pi มีให้ \"ตามที่เป็น\" โดยไม่มีประกันใดๆ เราไม่รับผิดชอบต่อความเสียหายหรือการสูญเสียใดๆ ที่เกิดจากการใช้แอปหรือการชำระเงิน Pi Network",
    termsSection6: "6. การเปลี่ยนแปลงข้อกำหนด:",
    termsSection6Text: "เราอาจอัปเดตข้อกำหนดเหล่านี้ได้ทุกเมื่อ การใช้แอปอย่างต่อเนื่องหมายความว่าคุณยอมรับข้อกำหนดใหม่",
    termsSection7: "7. ติดต่อ:",
    termsSection7Text: "สำหรับคำถาม ติดต่อ",
