    whitepaperTitle: "Flappy Pi Whitepaper",
    whitepaperDescription: "เอกสารทางเทคนิคและแผนงาน",
    whitepaperSection1: "1. บทนำ",
    whitepaperSection1Text: "Flappy Pi เป็นเกม play-to-earn Flappy Bird เกมแรกบน Pi Network ที่รวม gameplay แบบคลาสสิกกับเทคโนโลยีบล็อกเชน",
    whitepaperSection2: "2. กลไกเกม",
    whitepaperSection2Text: "ผู้เล่นควบคุมนก นำทางผ่านท่อในขณะที่เก็บเหรียญและหลีกเลี่ยงสิ่งกีดขวาง เกมมีหลายโหมดและ power-up",
    whitepaperSection3: "3. การรวม Pi Network",
    whitepaperSection3Text: "Flappy Pi ใช้โครงสร้างพื้นฐาน Pi Network สำหรับการชำระเงินที่ปลอดภัยและการยืนยันตัวตนผู้ใช้ รับประกันประสบการณ์การเล่นเกมที่ราบรื่น",
    whitepaperSection4: "4. Tokenomics",
    whitepaperSection4Text: "ผู้เล่นสามารถรับคริปโตเคอร์เรนซี Pi ผ่าน gameplay การแข่งขันและกิจกรรมพิเศษ เศรษฐกิจได้รับการออกแบบให้ยั่งยืนและยุติธรรม",
    whitepaperSection5: "5. การพัฒนาอนาคต",
    whitepaperSection5Text: "คุณสมบัติที่วางแผนไว้รวมถึง NFT collectibles การแข่งขันขั้นสูงและความเข้ากันได้ข้ามแพลตฟอร์ม",
    whitepaperSection6: "6. ติดต่อและชุมชน",
    whitepaperSection6Text: "สำหรับคำถาม ข้อเสนอแนะหรือคำขอความร่วมมือ ติดต่อ",
