    privacyTitle: "Datenschutzrichtlinie",
    privacyDescription: "Erfahren Sie, wie wir Ihre Daten und Privatsphäre schützen",
    privacySection1: "1. Datenerhebung:",
    privacySection1Text: "Flappy Pi sammelt nur die minimalen Daten, die für die Bereitstellung von Spielediensten erforderlich sind, wie Ihren Benutzernamen, Spielstand und Pi Network ID.",
    privacySection2: "2. Zahlungsdaten:",
    privacySection2Text: "Wenn Sie Pi-Zahlungen tätigen, verarbeiten wir die Transaktionsdetails über das Pi Network. Im Mainnet werden echte Pi-Transaktionen sicher vom Pi Network verarbeitet.",
    privacySection3: "3. Cookies und lokale Speicherung:",
    privacySection3Text: "Wir verwenden lokale Speicherung, um Ihren Spielstand und Ihre Einstellungen zu speichern. Keine Tracking-Cookies von Drittanbietern werden verwendet.",
    privacySection4: "4. Datenweitergabe:",
    privacySection4Text: "Wir verkaufen oder teilen Ihre persönlichen Daten nicht mit Dritten, außer wenn dies gesetzlich vorgeschrieben ist oder zur Verarbeitung von Pi Network-Zahlungen.",
    privacySection5: "5. Sicherheit:",
    privacySection5Text: "Wir verwenden branchenübliche Sicherheitsmaßnahmen zum Schutz Ihrer Daten. Kein System ist jedoch 100% sicher.",
    privacySection6: "6. Datenschutz für Kinder:",
    privacySection6Text: "Flappy Pi ist nicht für Kinder unter 13 Jahren bestimmt. Wir sammeln nicht absichtlich Daten von Kindern unter 13 Jahren.",
    privacySection7: "7. Richtlinienänderungen:",
    privacySection7Text: "Wir können diese Richtlinie aktualisieren. Die fortgesetzte Nutzung der App bedeutet, dass Sie die neue Richtlinie akzeptieren.",
    privacySection8: "8. Kontakt:",
    privacySection8Text: "Für Datenschutzfragen kontaktieren Sie",
    privacyContactEmail: "support@www.flappypi.xyz",
    
    termsTitle: "Nutzungsbedingungen",
    termsDescription: "Lesen Sie unsere Bedingungen und Bestimmungen",
    termsSection1: "1. Annahme der Bedingungen:",
    termsSection1Text: "Durch die Nutzung von Flappy Pi stimmen Sie diesen Nutzungsbedingungen zu. Wenn Sie nicht zustimmen, verwenden Sie bitte die App nicht.",
    termsSection2: "2. Pi Network-Zahlungen:",
    termsSection2Text: "Flappy Pi integriert sich in das Pi Network für In-App-Zahlungen. Alle Pi-Zahlungen im Testmodus verwenden das Pi Testnet und übertragen kein echtes Pi. Beim Wechsel zum Mainnet finden echte Pi-Transaktionen statt. Überprüfen Sie immer den Zahlungsmodus vor der Bestätigung einer Transaktion.",
    termsSection3: "3. Benutzerkonten:",
    termsSection3Text: "Sie sind verantwortlich für die Vertraulichkeit Ihres Kontos und alle Aktivitäten, die unter Ihrem Konto stattfinden.",
    termsSection4: "4. Spielinhalt:",
    termsSection4Text: "Alle Spiel-Assets, Grafiken und Inhalte sind Eigentum von Flappy Pi und dürfen ohne Erlaubnis nicht verwendet werden.",
