    termsSection5Text: "Flappy Pi wird \"wie besehen\" ohne jegliche Garantien bereitgestellt. Wir sind nicht verantwortlich für Schäden oder Verluste, die sich aus der Nutzung der App oder Pi Network-Zahlungen ergeben.",
    termsSection6: "6. Bedingungsänderungen:",
