    termsSection7: "7. Kontakt:",
    termsSection7Text: "Für Fragen kontaktieren Sie",
    termsContactEmail: "support@www.flappypi.xyz",
    
    whitepaperTitle: "Flappy Pi Whitepaper",
    whitepaperDescription: "Technische Dokumentation und Roadmap",
    whitepaperSection1: "1. Einführung",
    whitepaperSection1Text: "Flappy Pi ist das erste Play-to-Earn Flappy Bird Spiel im Pi Network, das klassisches Gameplay mit Blockchain-Technologie kombiniert.",
    whitepaperSection2: "2. Spielmechaniken",
    whitepaperSection2Text: "Spieler steuern einen Vogel, navigieren durch Röhren und sammeln dabei Münzen und vermeiden Hindernisse. Das Spiel bietet mehrere Modi und Power-ups.",
    whitepaperSection3: "3. Pi Network-Integration",
    whitepaperSection3Text: "Flappy Pi nutzt die Pi Network-Infrastruktur für sichere Zahlungen und Benutzerauthentifizierung und gewährleistet ein nahtloses Spielerlebnis.",
    whitepaperSection4: "4. Tokenomics",
    whitepaperSection4Text: "Spieler können Pi-Kryptowährung durch Gameplay, Turniere und besondere Events verdienen. Die Wirtschaft ist für Nachhaltigkeit und Fairness konzipiert.",
    whitepaperSection5: "5. Zukünftige Entwicklung",
    whitepaperSection5Text: "Geplante Features umfassen NFT-Sammlerstücke, erweiterte Turniere und plattformübergreifende Kompatibilität.",
