    privacyDescription: "데이터와 개인정보를 어떻게 보호하는지 알아보세요",
    privacySection1: "1. 데이터 수집:",
    privacySection1Text: "Flappy Pi는 게임 서비스를 제공하는 데 필요한 최소한의 데이터만 수집합니다. 사용자명, 게임 진행 상황, Pi Network ID 등이 포함됩니다.",
    privacySection2: "2. 결제 데이터:",
    privacySection2Text: "Pi 결제를 할 때 Pi Network를 통해 거래 세부사항을 처리합니다. 메인넷에서는 실제 Pi 거래가 Pi Network에 의해 안전하게 처리됩니다.",
    privacySection3: "3. 쿠키 및 로컬 저장소:",
    privacySection3Text: "게임 진행 상황과 설정을 저장하기 위해 로컬 저장소를 사용합니다. 타사 추적 쿠키는 사용하지 않습니다.",
    privacySection4: "4. 데이터 공유:",
    privacySection4Text: "법률에서 요구하거나 Pi Network 결제를 처리하기 위해 필요한 경우를 제외하고 개인 데이터를 제3자에게 판매하거나 공유하지 않습니다.",
    privacySection5: "5. 보안:",
    privacySection5Text: "데이터를 보호하기 위해 업계 표준 보안 조치를 사용합니다. 그러나 어떤 시스템도 100% 안전하지는 않습니다.",
    privacySection6: "6. 아동 개인정보 보호:",
    privacySection6Text: "Flappy Pi는 13세 미만의 아동을 대상으로 하지 않습니다. 13세 미만의 아동으로부터 의도적으로 데이터를 수집하지 않습니다.",
