    // Footer Documentation Translations
    privacyTitle: "سياسة الخصوصية",
    privacyDescription: "تعرف على كيفية حماية بياناتك وخصوصيتك",
    privacySection1: "1. جمع البيانات:",
    privacySection1Text: "Flappy Pi يجمع فقط الحد الأدنى من البيانات اللازمة لتقديم خدمات اللعبة، مثل اسم المستخدم وتقدم اللعبة ومعرف Pi Network الخاص بك.",
    privacySection2: "2. بيانات الدفع:",
    privacySection2Text: "عند إجراء مدفوعات Pi، نعالج تفاصيل المعاملات من خلال Pi Network. في الشبكة الرئيسية، تتم معالجة معاملات Pi الفعلية بأمان من قبل Pi Network.",
    privacySection3: "3. ملفات تعريف الارتباط والتخزين المحلي:",
    privacySection3Text: "نستخدم التخزين المحلي لحفظ تقدم اللعبة وإعداداتك. لا نستخدم ملفات تعريف الارتباط لتتبع الطرف الثالث.",
    privacySection4: "4. مشاركة البيانات:",
    privacySection4Text: "لا نبيع أو نشارك بياناتك الشخصية مع أطراف ثالثة، إلا عندما يطلب القانون ذلك أو لمعالجة مدفوعات Pi Network.",
    privacySection5: "5. الأمان:",
    privacySection5Text: "نستخدم إجراءات أمنية قياسية في الصناعة لحماية بياناتك. ومع ذلك، لا يوجد نظام آمن بنسبة 100%.",
    privacySection6: "6. خصوصية الأطفال:",
    privacySection6Text: "Flappy Pi غير مصمم للأطفال دون سن 13 عامًا. لا نجمع عمدًا بيانات من الأطفال دون سن 13 عامًا.",
    privacySection7: "7. تغييرات السياسة:",
    privacySection7Text: "قد نحدث هذه السياسة. الاستخدام المستمر للتطبيق يعني قبول السياسة الجديدة.",
    privacySection8: "8. الاتصال:",
    privacySection8Text: "للأسئلة المتعلقة بالخصوصية، اتصل بنا على",
    privacyContactEmail: "support@www.flappypi.xyz",
    
    termsTitle: "شروط الخدمة",
    termsDescription: "اقرأ شروطنا وأحكامنا",
    termsSection1: "1. قبول الشروط:",
    termsSection1Text: "باستخدام Flappy Pi، فإنك توافق على شروط الخدمة هذه. إذا كنت لا توافق، يرجى عدم استخدام التطبيق.",
    termsSection2: "2. مدفوعات Pi Network:",
    termsSection2Text: "Flappy Pi متكامل مع Pi Network للمدفوعات داخل التطبيق. جميع مدفوعات Pi في وضع الاختبار تستخدم Pi Testnet ولا تحول Pi فعلي. عند الانتقال إلى الشبكة الرئيسية، ستحدث معاملات Pi الفعلية. تحقق دائمًا من وضع الدفع قبل تأكيد المعاملة.",
    termsSection3: "3. حسابات المستخدمين:",
    termsSection3Text: "أنت مسؤول عن الحفاظ على سرية حسابك وجميع الأنشطة التي تحدث تحت حسابك.",
    termsSection4: "4. محتوى اللعبة:",
    termsSection4Text: "جميع أصول اللعبة والرسومات والمحتوى مملوكة لـ Flappy Pi ولا يمكن استخدامها بدون إذن.",
    termsSection5: "5. حدود المسؤولية:",
    termsSection5Text: "يتم توفير Flappy Pi \"كما هو\" دون أي ضمانات. نحن غير مسؤولين عن أي أضرار أو خسائر ناتجة عن استخدام التطبيق أو مدفوعات Pi Network.",
    termsSection6: "6. تغييرات الشروط:",
    termsSection6Text: "قد نحدث هذه الشروط في أي وقت. الاستخدام المستمر للتطبيق يعني قبول الشروط الجديدة.",
    termsSection7: "7. الاتصال:",
    termsSection7Text: "للأسئلة، اتصل بنا على",
    termsContactEmail: "support@www.flappypi.xyz",
    
