    privacyDescription: "Scopri come proteggiamo i tuoi dati e la tua privacy",
    privacySection1: "1. Raccolta dati:",
    privacySection1Text: "Flappy Pi raccoglie solo i dati minimi necessari per fornire servizi di gioco, come nome utente, progresso del gioco e il tuo Pi Network ID.",
    privacySection2: "2. Dati di pagamento:",
    privacySection2Text: "Quando effettui pagamenti Pi, elaboriamo i dettagli delle transazioni attraverso Pi Network. Nella mainnet, le transazioni Pi reali sono elaborate in sicurezza da Pi Network.",
